<#
One-shot script: appends the new feature-004 localization keys to all 9
shipped language JSON files (log.event.*, settings.language.*,
settings.toast.*restartPending, compact.languageRestart.*,
settings.button.restartNow, settings.journal.*, diagnostics.field.*,
diagnostics.check.*, diagnostics.outcome.*, diagnostics.languagePendingRestart,
diagnostics.report.title).

Mirrors the technique used for compact.miniLog.collapse in feature 003:
insert new "key": "value" lines just before the final closing brace, so
existing key order/formatting is untouched and the parity test
(LocalizationServiceTests.EveryShippedLanguage_HasNonEmptyTable_WithSameKeySetAsRussian)
passes for every language. Idempotent — skips keys that already exist.
#>

$ErrorActionPreference = 'Stop'
$root = "c:\Users\adm\Desktop\13\vibe\Steamoff\src\Steamoff.Core\Resources\Localization"
$languages = @('ru','en','de','fr','es','it','pt','pl','zh')

# Ordered list of (key, @{ lang = text }) pairs.
$entries = New-Object System.Collections.ArrayList
function Add-Entry([string]$key, [hashtable]$texts) {
    [void]$entries.Add(@{ Key = $key; Texts = $texts })
}

