# ---------- apply ----------
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

foreach ($lang in $languages) {
    $path = Join-Path $root "$lang.json"
    $text = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)

    # Locate the last closing brace.
    $lastBrace = $text.LastIndexOf('}')
    $head = $text.Substring(0, $lastBrace)
    $head = $head.TrimEnd("`r", "`n", " ")

    $added = 0
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append($head)

    foreach ($entry in $entries) {
        $key = $entry.Key
        if ($text.Contains("`"$key`":")) {
            continue
        }

        $value = $entry.Texts[$lang]
        if (-not $value) { $value = $entry.Texts['en'] }

        $escapedKey = $key.Replace('\', '\\').Replace('"', '\"')
        $escapedValue = $value.Replace('\', '\\').Replace('"', '\"')

        [void]$sb.Append(",`r`n  `"$escapedKey`": `"$escapedValue`"")
        $added++
    }

    [void]$sb.Append("`r`n}")
    [void]$sb.Append("`r`n")

    if ($added -gt 0) {
        [System.IO.File]::WriteAllText($path, $sb.ToString(), $utf8NoBom)
    }

    Write-Output "$lang.json -> added $added keys"
}
